api.look('agent');
const cx = api.w/2, cy = 330;
const k = api.seg(t, 0, 1.2);
api.shape('doc', cx, cy, 200, {c:'a2', w:4, k});
api.path('M-100 -60 L0 20 L100 -60', {x:cx, y:cy-10, s:1, c:'a2', w:4, k:api.seg(t,0.6,1.6)});
api.counter(12, cx, cy+200, {k:api.seg(t,0.8,2.6), size:72, c:'accent'});
api.text('emails answered', cx, cy+260, {size:22, c:'fg', align:'center', k:api.seg(t,1.8,2.8)});
api.swarm(24, t, {mode:'burst', cx, cy, rx:140, ry:100, c:'a2'});
api.say('Twelve emails answered', 0.3, 3.3);

api.look('agent');
const cx = api.w/2;
api.cam(0, 0, api.lerp(1, 1.08, api.ease(api.seg(t,0,6))), 0);
api.text('Inbox', cx, 90, {size:36, c:'fg', align:'center', weight:700});
const cols = 3, rows = 4, cw = 100, ch = 80, gx = 18, gy = 22;
const x0 = cx - (cols*cw + (cols-1)*gx)/2, y0 = 150;
for (let i = 0; i < 12; i++) {
  const r = Math.floor(i/cols), q = i % cols;
  const k = api.stag(t, i, {gap:0.3, dur:0.5, from:0.3});
  const x = x0 + q*(cw+gx) + cw/2, y = y0 + r*(ch+gy) + ch/2;
  api.box(x, y, cw, ch, {c:'a2', w:3, k, fill:'panel'});
  api.path('M-34 -18 L0 8 L34 -18', {x, y, s:1, c:'a2', w:3, k});
  const d = api.seg(t, 0.3+i*0.3+0.4, 0.3+i*0.3+0.9);
  if (d > 0) api.shape('check', x+30, y+22, 30, {c:'good', w:5, k:d});
}
api.counter(Math.round(12*api.seg(t,0.5,4.5)), cx, 590, {size:56, c:'accent', suf:' / 12'});
api.say('Each one answered', 0.4, 5.5);

api.look('agent');
const cx = api.w/2, cy = 330;
api.text('Website', cx, 90, {size:36, c:'fg', align:'center', weight:700});
api.box(cx, cy, 330, 200, {c:'fg', w:3, fill:'panel'});
api.line(cx-165, cy-60, cx+165, cy-60, {c:'dim', w:2});
api.text('yuigui.com', cx-150, cy-82, {size:16, c:'dim'});
const nodes = [cx-90, cx+90];
const fixed = [api.seg(t,2.2,3.2), api.seg(t,3.8,4.8)];
for (let i = 0; i < 2; i++) {
  const x = nodes[i], y = cy+30;
  api.circle(x, y, 22, {c:'a3', w:4, fill:'panel', k:api.seg(t,0.2+i*0.3,0.9+i*0.3)});
  api.text('link', x, y+50, {size:17, c:'dim', align:'center'});
  if (i === 0) api.line(x-70, y, x-30, y, {c:'a3', w:4});
  api.line(x+30, y, x+70, y, {c:'a3', w:4});
  if (fixed[i] === 0) {
    api.shape('cross', x, y, 26, {c:'bad', w:5, k:api.seg(t,0.9+i*0.3,1.6+i*0.3)});
  } else {
    api.circle(x, y, 22+fixed[i]*10, {c:'good', w:4, a:1-fixed[i]*0.5});
    api.shape('check', x, y, 28, {c:'good', w:5, k:fixed[i]});
  }
}
api.counter(Math.round(2*api.seg(t,3,5)), cx, 600, {size:56, c:'accent', suf:' fixed'});
api.say('Two broken links fixed', 0.4, 5.5);

api.look('agent');
const cx = api.w/2, cy = 340;
api.text('Newsletter', cx, 90, {size:36, c:'fg', align:'center', weight:700});
api.rect(cx-130, cy-190, 260, 380, {c:'fg', w:3, fill:'panel', r:10, k:api.seg(t,0,1)});
api.text('Next week', cx-105, cy-150, {size:24, c:'accent', weight:700, k:api.seg(t,0.8,1.6)});
api.line(cx-105, cy-125, cx+105, cy-125, {c:'dim', w:2, k:api.seg(t,1,1.6)});
api.rect(cx-105, cy-105, 210, 90, {c:'a3', w:2, r:6, k:api.seg(t,1.6,2.4)});
for (let i = 0; i < 6; i++) {
  const k = api.seg(t, 2.2+i*0.35, 2.9+i*0.35);
  api.line(cx-105, cy+10+i*26, cx-105+(i%3===2?120:210), cy+10+i*26, {c:'a2', w:4, k});
}
const py = cy + 150;
api.path('M0 0 L60 -60 L80 -40 L20 20 L-10 30 Z', {x:cx+60+Math.sin(t*3)*8, y:py-api.seg(t,2,5)*200, s:1, c:'warn', w:3, k:api.seg(t,2,3)});
api.say('Next week newsletter drafted', 0.4, 5.5);

api.look('agent');
const cx = api.w/2;
api.text('Your day', cx, 100, {size:40, c:'fg', align:'center', weight:700, k:api.seg(t,0,1)});
const items = [
  {n:12, s:'emails', c:'a2'},
  {n:2, s:'links fixed', c:'a3'},
  {n:1, s:'newsletter', c:'accent'}
];
for (let i = 0; i < 3; i++) {
  const k = api.stag(t, i, {gap:0.9, dur:0.8, from:0.6});
  const y = 250 + i*140;
  api.circle(cx, y, 56*api.ease(k), {c:items[i].c, w:5, fill:'panel'});
  api.counter(items[i].n, cx, y+12, {k, size:48, c:items[i].c});
  api.text(items[i].s, cx, y+82, {size:20, c:'fg', align:'center', k});
}
api.say('A full, finished day', 0.5, 5.5);
